-- origin=oracle row_preserving=True check=rows_equal
CREATE VIEW v_frpm AS SELECT frpm.CDSCode AS CDSCode, frpm.`Academic Year` AS `Academic Year`, frpm.`County Code` AS `County Code`, frpm.`District Code` AS `District Code`, frpm.`School Code` AS `School Code`, frpm.`County Name` AS `County Name`, frpm.`District Name` AS `District Name`, frpm.`School Name` AS `School Name`, frpm.`District Type` AS `District Type`, frpm.`School Type` AS `School Type`, frpm.`Educational Option Type` AS `Educational Option Type`, frpm.`NSLP Provision Status` AS `NSLP Provision Status`, frpm.`Charter School (Y/N)` AS `Charter School (Y/N)`, frpm.`Charter School Number` AS `Charter School Number`, frpm.`Charter Funding Type` AS `Charter Funding Type`, frpm.IRC AS IRC, frpm.`Low Grade` AS `Low Grade`, frpm.`High Grade` AS `High Grade`, frpm.`Enrollment (K-12)` AS `Enrollment (K-12)`, frpm.`Free Meal Count (K-12)` AS `Free Meal Count (K-12)`, frpm.`Percent (%) Eligible Free (K-12)` AS `Percent (%) Eligible Free (K-12)`, frpm.`FRPM Count (K-12)` AS `FRPM Count (K-12)`, frpm.`Percent (%) Eligible FRPM (K-12)` AS `Percent (%) Eligible FRPM (K-12)`, frpm.`Enrollment (Ages 5-17)` AS `Enrollment (Ages 5-17)`, frpm.`Free Meal Count (Ages 5-17)` AS `Free Meal Count (Ages 5-17)`, frpm.`Percent (%) Eligible Free (Ages 5-17)` AS `Percent (%) Eligible Free (Ages 5-17)`, frpm.`FRPM Count (Ages 5-17)` AS `FRPM Count (Ages 5-17)`, frpm.`Percent (%) Eligible FRPM (Ages 5-17)` AS `Percent (%) Eligible FRPM (Ages 5-17)`, frpm.`2013-14 CALPADS Fall 1 Certification Status` AS `2013-14 CALPADS Fall 1 Certification Status`, schools.NCESDist AS schools_NCESDist, schools.NCESSchool AS schools_NCESSchool, schools.StatusType AS schools_StatusType, schools.County AS schools_County, schools.District AS schools_District, schools.School AS schools_School, schools.Street AS schools_Street, schools.StreetAbr AS schools_StreetAbr, schools.City AS schools_City, schools.Zip AS schools_Zip, schools.State AS schools_State, schools.MailStreet AS schools_MailStreet, schools.MailStrAbr AS schools_MailStrAbr, schools.MailCity AS schools_MailCity, schools.MailZip AS schools_MailZip, schools.MailState AS schools_MailState, schools.Phone AS schools_Phone, schools.Ext AS schools_Ext, schools.Website AS schools_Website, schools.OpenDate AS schools_OpenDate, schools.ClosedDate AS schools_ClosedDate, schools.Charter AS schools_Charter, schools.CharterNum AS schools_CharterNum, schools.FundingType AS schools_FundingType, schools.DOC AS schools_DOC, schools.DOCType AS schools_DOCType, schools.SOC AS schools_SOC, schools.SOCType AS schools_SOCType, schools.EdOpsCode AS schools_EdOpsCode, schools.EdOpsName AS schools_EdOpsName, schools.EILCode AS schools_EILCode, schools.EILName AS schools_EILName, schools.GSoffered AS schools_GSoffered, schools.GSserved AS schools_GSserved, schools.Virtual AS schools_Virtual, schools.Magnet AS schools_Magnet, schools.Latitude AS schools_Latitude, schools.Longitude AS schools_Longitude, schools.AdmFName1 AS schools_AdmFName1, schools.AdmLName1 AS schools_AdmLName1, schools.AdmEmail1 AS schools_AdmEmail1, schools.AdmFName2 AS schools_AdmFName2, schools.AdmLName2 AS schools_AdmLName2, schools.AdmEmail2 AS schools_AdmEmail2, schools.AdmFName3 AS schools_AdmFName3, schools.AdmLName3 AS schools_AdmLName3, schools.AdmEmail3 AS schools_AdmEmail3, schools.LastUpdate AS schools_LastUpdate FROM frpm LEFT JOIN schools AS schools ON frpm.CDSCode = schools.CDSCode;

-- origin=oracle row_preserving=True check=rows_equal
CREATE VIEW v_satscores AS SELECT satscores.cds AS cds, satscores.rtype AS rtype, satscores.sname AS sname, satscores.dname AS dname, satscores.cname AS cname, satscores.enroll12 AS enroll12, satscores.NumTstTakr AS NumTstTakr, satscores.AvgScrRead AS AvgScrRead, satscores.AvgScrMath AS AvgScrMath, satscores.AvgScrWrite AS AvgScrWrite, satscores.NumGE1500 AS NumGE1500, cds.NCESDist AS cds_NCESDist, cds.NCESSchool AS cds_NCESSchool, cds.StatusType AS cds_StatusType, cds.County AS cds_County, cds.District AS cds_District, cds.School AS cds_School, cds.Street AS cds_Street, cds.StreetAbr AS cds_StreetAbr, cds.City AS cds_City, cds.Zip AS cds_Zip, cds.State AS cds_State, cds.MailStreet AS cds_MailStreet, cds.MailStrAbr AS cds_MailStrAbr, cds.MailCity AS cds_MailCity, cds.MailZip AS cds_MailZip, cds.MailState AS cds_MailState, cds.Phone AS cds_Phone, cds.Ext AS cds_Ext, cds.Website AS cds_Website, cds.OpenDate AS cds_OpenDate, cds.ClosedDate AS cds_ClosedDate, cds.Charter AS cds_Charter, cds.CharterNum AS cds_CharterNum, cds.FundingType AS cds_FundingType, cds.DOC AS cds_DOC, cds.DOCType AS cds_DOCType, cds.SOC AS cds_SOC, cds.SOCType AS cds_SOCType, cds.EdOpsCode AS cds_EdOpsCode, cds.EdOpsName AS cds_EdOpsName, cds.EILCode AS cds_EILCode, cds.EILName AS cds_EILName, cds.GSoffered AS cds_GSoffered, cds.GSserved AS cds_GSserved, cds.Virtual AS cds_Virtual, cds.Magnet AS cds_Magnet, cds.Latitude AS cds_Latitude, cds.Longitude AS cds_Longitude, cds.AdmFName1 AS cds_AdmFName1, cds.AdmLName1 AS cds_AdmLName1, cds.AdmEmail1 AS cds_AdmEmail1, cds.AdmFName2 AS cds_AdmFName2, cds.AdmLName2 AS cds_AdmLName2, cds.AdmEmail2 AS cds_AdmEmail2, cds.AdmFName3 AS cds_AdmFName3, cds.AdmLName3 AS cds_AdmLName3, cds.AdmEmail3 AS cds_AdmEmail3, cds.LastUpdate AS cds_LastUpdate FROM satscores LEFT JOIN schools AS cds ON satscores.cds = cds.CDSCode;
